toolArgs.file_text:
@* Left sidebar showing available channels *@

<div class="channel-list">
    <h5 class="channel-list-header">Channels</h5>
    @foreach (var channel in Channels)
    {
        <ChannelItem Channel="channel"
                     IsActive="channel.Id == ActiveChannelId"
                     OnSelected="OnChannelSelected" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int? ActiveChannelId { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnChannelSelected { get; set; }
}

@* Right collapsible thread panel *@

<div class="thread-panel">
    <div class="thread-header">
        <h6>Thread</h6>
        <button class="btn-close" @onclick="OnClose"></button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <MessageItem Message="RootMessage" ShowReplyButton="false" OnReact="OnReact" />
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <MessageItem Message="reply" ShowReplyButton="false" OnReact="OnReact" />
            }
        </div>

        <MessageInput Placeholder="Reply in thread..." ButtonLabel="Reply" OnSubmit="OnReply" />
    }
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback OnClose { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnReply { get; set; }
    [Parameter] public EventCallback<string> OnReact { get; set; }
}

@* Main message area with header, scrollable messages, and input *@
@implements IAsyncDisposable
@inject IJSRuntime JS

<div class="message-area">
    <div class="message-area-header">
        <h5><span class="channel-hash">#</span> @ChannelName</h5>
        @if (!string.IsNullOrWhiteSpace(ChannelDescription))
        {
            <p class="channel-desc-text">@ChannelDescription</p>
        }
    </div>

    <div class="message-list" @ref="_messageListRef" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages...</div>
        }
        @foreach (var message in Messages)
        {
            <MessageItem Message="message"
                         ThreadReplyCount="GetThreadReplyCount(message.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="async (emoji) => await OnReact.InvokeAsync((message.Id, emoji))" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")" OnSubmit="OnSend" />
</div>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string? ChannelDescription { get; set; }
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter, EditorRequired] public EventCallback<string> OnSend { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter, EditorRequired] public EventCallback OnLoadMore { get; set; }

    private ElementReference _messageListRef;
    private IJSObjectReference? _module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>("import",
                "./_content/sv-fec130c8dd104e30a50e4057573c58f1/Components/Pages/Chat/MessageArea.razor.js");
            await ScrollToBottom();
        }
    }

    private async Task ScrollToBottom()
    {
        if (_module is not null)
        {
            await _module.InvokeVoidAsync("scrollToBottom", _messageListRef);
        }
    }

    private async Task HandleScroll()
    {
        if (_module is not null)
        {
            var scrollTop = await _module.InvokeAsync<double>("getScrollTop", _messageListRef);
            if (scrollTop <= 0 && !IsLoadingMore)
            {
                await OnLoadMore.InvokeAsync();
            }
        }
    }

    private int GetThreadReplyCount(int messageId) =>
        ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            await _module.DisposeAsync();
        }
    }
}

