{"file_text": "@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    <ChannelList Channels="_channels"
                 ActiveChannelId="_activeChannelId"
                 OnChannelSelected="SelectChannel" />

    <div class="chat-main @(_threadOpen ? "with-thread" : "")">
        @if (_activeChannel is not null)
        {
            <MessageArea ChannelName="@_activeChannel.Name"
                         ChannelDescription="@_activeChannel.Description"
                         Messages="_messages"
                         ThreadReplyCounts="_threadReplyCounts"
                         IsLoadingMore="_isLoadingMore"
                         OnOpenThread="OpenThread"
                         OnSend="SendMessage"
                         OnReact="HandleReaction"
                         OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply"
                     OnReact="HandleThreadReaction" />
    }
</div>

@code {
    private List<Channel> _channels = [];
    private int? _activeChannelId;
    private Channel? _activeChannel;
    private List<Message> _messages = [];
    private Dictionary<int, int> _threadReplyCounts = new();
    private bool _isLoadingMore;

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _threadReplyCounts = BuildThreadReplyCounts(_messages);
        CloseThread();
        await ChatService.MarkChannelReadAsync(channelId);

        // Update unread count in local state
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = _channels[idx];
            _channels[idx] = ch with { UnreadCount = 0 };
        }
    }

    private async Task LoadMoreMessages()
    {
        if (_activeChannelId is null || _isLoadingMore) return;
        _isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(_activeChannelId.Value, _messages.Count, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            foreach (var (id, count) in BuildThreadReplyCounts(older))
            {
                _threadReplyCounts.TryAdd(id, count);
            }
        }

        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (_activeChannelId is null) return;
        var message = await ChatService.SendMessageAsync(_activeChannelId.Value, content, null);
        _messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_activeChannelId is null || _threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update reply count
        _threadReplyCounts[_threadRootMessage.Id] =
            _threadReplyCounts.GetValueOrDefault(_threadRootMessage.Id) + 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to reflect updated reaction
        if (_activeChannelId is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _messages.Count);
        }
    }

    private async Task HandleThreadReaction(string emoji)
    {
        // For simplicity, react to root message from thread panel
        if (_threadRootMessage is not null)
        {
            await ChatService.AddReactionAsync(_threadRootMessage.Id, emoji);
        }
    }

    private static Dictionary<int, int> BuildThreadReplyCounts(List<Message> messages)
    {
        var counts = new Dictionary<int, int>();
        foreach (var msg in messages)
        {
            if (msg.ReplyToId is not null)
            {
                counts[msg.ReplyToId.Value] = counts.GetValueOrDefault(msg.ReplyToId.Value) + 1;
            }
        }
        return counts;
    }
}
